package main

import (
 "bytes"
 "context"
 "crypto/aes"
 "crypto/cipher"
 "crypto/hmac"
 "crypto/rand"
 "crypto/sha256"
 "database/sql"
 "encoding/hex"
 "encoding/json"
 "errors"
 "io"
 "log/slog"
 "net"
 "net/http"
 "net/url"
 "strings"
 "strconv"
 "time"
)

var webhookEvents=map[string]bool{"collection.succeeded":true,"refund.completed":true,"transfer.completed":true,"transfer.approval_required":true,"transfer.approved":true,"transfer.rejected":true,"fraud.case.opened":true,"fraud.case.resolved":true,"reconciliation.import.completed":true}
var webhookHTTP=&http.Client{Timeout:8*time.Second,CheckRedirect:func(*http.Request,[]*http.Request)error{return http.ErrUseLastResponse},Transport:&http.Transport{Proxy:nil,DialContext:guardedWebhookDial,TLSHandshakeTimeout:4*time.Second,ResponseHeaderTimeout:5*time.Second,MaxIdleConns:20,IdleConnTimeout:30*time.Second}}
func webhookKey()([]byte,error){key,err:=hex.DecodeString(strings.TrimSpace(env("WEBHOOK_ENCRYPTION_KEY","")));if err!=nil||len(key)!=32{return nil,errors.New("WEBHOOK_ENCRYPTION_KEY must be 32-byte hex")};return key,nil}
func sealWebhookSecret(secret string)([]byte,error){key,err:=webhookKey();if err!=nil{return nil,err};block,err:=aes.NewCipher(key);if err!=nil{return nil,err};gcm,err:=cipher.NewGCM(block);if err!=nil{return nil,err};nonce:=make([]byte,gcm.NonceSize());if _,err=rand.Read(nonce);err!=nil{return nil,err};return append(nonce,gcm.Seal(nil,nonce,[]byte(secret),nil)...),nil}
func openWebhookSecret(ciphertext []byte)(string,error){key,err:=webhookKey();if err!=nil{return "",err};block,err:=aes.NewCipher(key);if err!=nil{return "",err};gcm,err:=cipher.NewGCM(block);if err!=nil{return "",err};if len(ciphertext)<gcm.NonceSize(){return "",errors.New("invalid encrypted webhook secret")};nonce:=ciphertext[:gcm.NonceSize()];plain,err:=gcm.Open(nil,nonce,ciphertext[gcm.NonceSize():],nil);return string(plain),err}
func publicWebhookIP(ip net.IP)bool{return ip!=nil&&ip.IsGlobalUnicast()&&!ip.IsPrivate()&&!ip.IsLoopback()&&!ip.IsLinkLocalUnicast()&&!ip.IsLinkLocalMulticast()&&!ip.IsMulticast()&&!ip.IsUnspecified()}
func validateWebhookURL(raw string)error{u,err:=url.ParseRequestURI(raw);if err!=nil||u.Scheme!="https"||u.Hostname()==""||u.User!=nil||u.Fragment!=""{return errors.New("webhook URL must be an HTTPS URL without credentials or a fragment")};ctx,cancel:=context.WithTimeout(context.Background(),3*time.Second);defer cancel();ips,err:=net.DefaultResolver.LookupIPAddr(ctx,u.Hostname());if err!=nil||len(ips)==0{return errors.New("webhook host must resolve to a public IP")};for _,item:=range ips{if !publicWebhookIP(item.IP){return errors.New("webhook host resolves to a non-public IP")}};return nil}
func guardedWebhookDial(ctx context.Context,network,address string)(net.Conn,error){host,port,err:=net.SplitHostPort(address);if err!=nil{return nil,err};ips,err:=net.DefaultResolver.LookupIPAddr(ctx,host);if err!=nil{return nil,err};if len(ips)==0{return nil,errors.New("webhook host did not resolve")};for _,item:=range ips{if !publicWebhookIP(item.IP){return nil,errors.New("webhook DNS resolved to a blocked address")}};dialer:=net.Dialer{Timeout:4*time.Second};var last error;for _,item:=range ips{conn,e:=dialer.DialContext(ctx,network,net.JoinHostPort(item.IP.String(),port));if e==nil{return conn,nil};last=e};return nil,last}
func (a *App) webhookEndpoints(w http.ResponseWriter,r *http.Request,parts []string){org:=currentOrgID(r,a.orgID);if len(parts)==1&&r.Method==http.MethodPost{var in struct{URL string `json:"url"`;Events []string `json:"events"`};if decode(r,&in)!=nil||len(in.Events)==0||len(in.Events)>20{bad(w,r,"an HTTPS URL and one or more event types are required");return};if err:=validateWebhookURL(in.URL);err!=nil{bad(w,r,err.Error());return};for _,event:=range in.Events{if !webhookEvents[event]{bad(w,r,"unsupported webhook event: "+event);return}};raw:=make([]byte,32);if _,err:=rand.Read(raw);err!=nil{writeJSON(w,500,problem{Error:"secret generation failed"});return};secret:=hex.EncodeToString(raw);ciphertext,err:=sealWebhookSecret(secret);if err!=nil{writeJSON(w,503,problem{Error:"webhook secret encryption is not configured",RequestID:requestID(r)});return};id:="whk_"+newID();_,err=a.db.ExecContext(r.Context(),`INSERT INTO webhook_endpoints(id,organization_id,url,secret_ciphertext,events) VALUES($1,$2,$3,$4,$5::jsonb)`,id,org,in.URL,ciphertext,string(mustJSON(in.Events)));if err!=nil{writeJSON(w,500,problem{Error:"webhook endpoint could not be registered"});return};writeJSON(w,201,map[string]any{"id":id,"url":in.URL,"events":in.Events,"status":"active","signing_secret":secret,"warning":"copy this signing secret now; it will not be shown again"});return};if len(parts)==1&&r.Method==http.MethodGet{rows,err:=a.db.QueryContext(r.Context(),`SELECT id,url,events,status,created_at FROM webhook_endpoints WHERE organization_id=$1 ORDER BY created_at DESC`,org);if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer rows.Close();data:=[]map[string]any{};for rows.Next(){var id,u,status string;var events []byte;var created time.Time;if rows.Scan(&id,&u,&events,&status,&created)==nil{var list []string;_ = json.Unmarshal(events,&list);data=append(data,map[string]any{"id":id,"url":u,"events":list,"status":status,"created_at":created})}};writeJSON(w,200,map[string]any{"data":data});return};if len(parts)==3&&parts[2]=="disable"&&r.Method==http.MethodPost{res,err:=a.db.ExecContext(r.Context(),`UPDATE webhook_endpoints SET status='disabled' WHERE id=$1 AND organization_id=$2`,parts[1],org);if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};n,_:=res.RowsAffected();if n==0{notFound(w,r)}else{writeJSON(w,200,map[string]string{"id":parts[1],"status":"disabled"})};return};notFound(w,r)}
func (a *App) webhookDeliveries(w http.ResponseWriter,r *http.Request){org:=currentOrgID(r,a.orgID);rows,err:=a.db.QueryContext(r.Context(),`SELECT id,endpoint_id,event_id,event_type,attempts,status,next_attempt_at,last_http_status,last_error,created_at FROM webhook_deliveries WHERE organization_id=$1 ORDER BY created_at DESC LIMIT 100`,org);if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer rows.Close();data:=[]map[string]any{};for rows.Next(){var id,endpoint,event,eventType,status string;var attempts int;var next,created time.Time;var code sql.NullInt64;var last sql.NullString;if rows.Scan(&id,&endpoint,&event,&eventType,&attempts,&status,&next,&code,&last,&created)==nil{data=append(data,map[string]any{"id":id,"endpoint_id":endpoint,"event_id":event,"event_type":eventType,"attempt_count":attempts,"status":status,"next_attempt_at":next,"last_http_status":nullableInt(code),"last_error":nullableNull(last),"created_at":created})}};writeJSON(w,200,map[string]any{"data":data})}
func nullableInt(v sql.NullInt64)any{if !v.Valid{return nil};return v.Int64}
func (a *App) runOutboxWorker(ctx context.Context){ticker:=time.NewTicker(time.Second);defer ticker.Stop();for{select{case <-ctx.Done():return;case <-ticker.C:if err:=a.publishOutboxOne(ctx);err!=nil{slog.Error("outbox publish", "error",err)};if err:=a.deliverWebhookOne(ctx);err!=nil{slog.Error("webhook delivery", "error",err)}}}}
func (a *App) publishOutboxOne(ctx context.Context)error{tx,err:=a.db.BeginTx(ctx,nil);if err!=nil{return err};defer tx.Rollback();var id,org,event string;err=tx.QueryRowContext(ctx,`SELECT id,organization_id,event_type FROM outbox_events WHERE published_at IS NULL ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED`).Scan(&id,&org,&event);if err==sql.ErrNoRows{return nil};if err!=nil{return err};_,err=tx.ExecContext(ctx,`INSERT INTO webhook_deliveries(id,organization_id,endpoint_id,event_id,event_type) SELECT 'whd_'||substr(md5(random()::text||clock_timestamp()::text),1,24),$1,w.id,$2,$3 FROM webhook_endpoints w WHERE w.organization_id=$1 AND w.status='active' AND w.events ? $3 ON CONFLICT(organization_id,endpoint_id,event_id) DO NOTHING`,org,id,event);if err==nil{_,err=tx.ExecContext(ctx,`UPDATE outbox_events SET published_at=now() WHERE id=$1 AND organization_id=$2`,id,org)};if err!=nil{return err};return tx.Commit()}
type claimedDelivery struct{id,endpointID,eventID,eventType,url string;secretCipher []byte;payload []byte;created time.Time;attempt int}
func (a *App) claimDelivery(ctx context.Context)(claimedDelivery,error){
 tx,err:=a.db.BeginTx(ctx,nil);if err!=nil{return claimedDelivery{},err};defer tx.Rollback();var d claimedDelivery
 err=tx.QueryRowContext(ctx,`SELECT d.id,d.endpoint_id,d.event_id FROM webhook_deliveries d JOIN webhook_endpoints w ON w.id=d.endpoint_id AND w.organization_id=d.organization_id WHERE w.status='active' AND ((d.status IN ('queued','retrying') AND d.next_attempt_at<=now()) OR (d.status='sending' AND d.updated_at<now()-interval '2 minutes')) ORDER BY d.next_attempt_at LIMIT 1 FOR UPDATE OF d SKIP LOCKED`).Scan(&d.id,&d.endpointID,&d.eventID);if err!=nil{return claimedDelivery{},err}
 if _,err=tx.ExecContext(ctx,`UPDATE webhook_deliveries SET status='sending',attempts=attempts+1,updated_at=now() WHERE id=$1`,d.id);err!=nil{return claimedDelivery{},err}
 err=tx.QueryRowContext(ctx,`SELECT d.event_type,d.attempts,w.url,w.secret_ciphertext,o.payload,o.created_at FROM webhook_deliveries d JOIN webhook_endpoints w ON w.id=d.endpoint_id AND w.organization_id=d.organization_id JOIN outbox_events o ON o.id=d.event_id AND o.organization_id=d.organization_id WHERE d.id=$1`,d.id).Scan(&d.eventType,&d.attempt,&d.url,&d.secretCipher,&d.payload,&d.created);if err!=nil{return claimedDelivery{},err};if err=tx.Commit();err!=nil{return claimedDelivery{},err};return d,nil
}
func (a *App) deliverWebhookOne(ctx context.Context)error{d,err:=a.claimDelivery(ctx);if err==sql.ErrNoRows{return nil};if err!=nil{return err};secret,err:=openWebhookSecret(d.secretCipher);var statusCode int;var deliveryErr string;if err==nil{var data json.RawMessage=d.payload;envelope,_:=json.Marshal(map[string]any{"id":d.eventID,"type":d.eventType,"created_at":d.created,"data":data});timestamp:=time.Now().UTC().Unix();mac:=hmac.New(sha256.New,[]byte(secret));_,_=mac.Write([]byte(strconv.FormatInt(timestamp,10)+"."));_,_=mac.Write(envelope);signature:=hex.EncodeToString(mac.Sum(nil));req,e:=http.NewRequestWithContext(ctx,http.MethodPost,d.url,bytes.NewReader(envelope));if e!=nil{err=e}else{req.Header.Set("Content-Type","application/json");req.Header.Set("X-AegisPay-Event-ID",d.eventID);req.Header.Set("X-AegisPay-Timestamp",strconv.FormatInt(timestamp,10));req.Header.Set("X-AegisPay-Signature","v1="+signature);resp,e:=webhookHTTP.Do(req);if e!=nil{err=e}else{statusCode=resp.StatusCode;_,_=io.Copy(io.Discard,io.LimitReader(resp.Body,4096));_ = resp.Body.Close();if statusCode<200||statusCode>=300{err=errors.New("endpoint returned non-success status")}}}}
 if err!=nil{deliveryErr=err.Error()};nextStatus:="delivered";var nextAttempt any;if err!=nil{if d.attempt>=12{nextStatus="failed"}else{nextStatus="retrying";delay:=time.Second*time.Duration(1<<min(d.attempt,10));nextAttempt=time.Now().Add(delay)}};_,dbErr:=a.db.ExecContext(ctx,`UPDATE webhook_deliveries SET status=$2,last_http_status=NULLIF($3,0),last_error=NULLIF($4,''),next_attempt_at=COALESCE($5,next_attempt_at),updated_at=now() WHERE id=$1`,d.id,nextStatus,statusCode,deliveryErr,nextAttempt);if dbErr!=nil{return dbErr};if err!=nil{slog.Warn("webhook endpoint delivery failed","delivery_id",d.id,"attempt",d.attempt,"error",deliveryErr)};return nil}
